-- =====================================================================
--  PATCH 245 — KJV corpus, part 3 of 9
--
--  Judges 18:7  ->  1 Chronicles 6:43   (3,500 verses)
--
--  Split because the whole KJV is ~6MB of SQL and patches are applied
--  as a single request body. Parts are independent and idempotent —
--  order does not matter, and re-running one changes nothing.
--
--  Requires patch 241 (schema). Text is public-domain KJV, cleaned on
--  load: translator marginal notes (brace groups containing a colon)
--  removed; KJV italics (brace groups without one) unwrapped so the
--  supplied word remains. See patch 241's header.
-- =====================================================================

ON CONFLICT (translation, book_number, chapter, verse)
  DO UPDATE SET text = EXCLUDED.text;

DO $$
DECLARE v_n INT;
BEGIN
  SELECT COUNT(*) INTO v_n FROM public.bible_verses WHERE translation='kjv';
  RAISE NOTICE 'patch 245 OK — part 3/9 loaded; corpus now % verses', v_n;
END $$;
